"""Offline paired decision-prompt comparison. No generated tutoring or judge calls."""
from pathlib import Path
import collections,csv,importlib.util,json,math
H=Path(__file__).resolve().parent;ROOT=H.parents[1]
spec=importlib.util.spec_from_file_location('decision_run',H/'run.py');r=importlib.util.module_from_spec(spec);spec.loader.exec_module(r)
cfg=r.prepare();rows=r.base.rows();out=[];newcorrect=oldcorrect=corrected=regressed=0;cost=0;invalid=0;incomplete=0;reasoning=0
for i in cfg['indices']:
 path=H/'traces'/f'astra-{i:03d}.json'
 if not path.exists():continue
 n=r.load(path);oldpath=ROOT/'experiments/astra-decision-pilot/traces'/f'astra-{i:03d}.json';old=r.load(oldpath)
 assert r.sha(oldpath.read_bytes())==cfg['baseline_hashes'][str(i)]
 assert n['payload_sha256']==r.sha(r.enc(r.payload(i)))==cfg['request_hashes'][str(i)]
 assert n['status']=='complete',n.get('error')
 assert {k:v for k,v in n['payload'].items() if k!='input'}=={k:v for k,v in old['payload'].items() if k!='input'}
 pred=r.base.parse(n['response'],'llm');assert pred==n['prediction'];gold=rows[i]['dimension'];newok=pred==gold;oldok=old['prediction']==gold
 newcorrect+=newok;oldcorrect+=oldok;corrected+=newok and not oldok;regressed+=oldok and not newok;invalid+=pred not in ['scaffolding','rigor'];incomplete+=n['response']['status']!='completed';cost+=r.cost(n['usage']);assert abs(r.cost(n['usage'])-n['cost_usd'])<1e-9
 reasoning+=n['usage'].get('output_tokens_details',{}).get('reasoning_tokens',0)
 out.append({'moment_number':i+1,'source_index':i,'reference':gold,'publisher_prompt_decision':pred,'publisher_prompt_correct':newok,'previous_prompt_decision':old['prediction'],'previous_prompt_correct':oldok,'changed_decision':pred!=old['prediction'],'cost_usd':n['cost_usd']})
n=len(out);groups={label:{'n':sum(x['reference']==label for x in out),'new_correct':sum(x['reference']==label and x['publisher_prompt_correct'] for x in out),'old_correct':sum(x['reference']==label and x['previous_prompt_correct'] for x in out)} for label in ['scaffolding','rigor']}
disc=corrected+regressed;pvalue=min(1.,2*sum(math.comb(disc,k) for k in range(min(corrected,regressed)+1))/2**disc) if disc else 1.
res={'status':'complete' if n==20 else 'partial','n':n,'new_correct':newcorrect,'old_correct':oldcorrect,'new_accuracy':newcorrect/n if n else None,'old_accuracy':oldcorrect/n if n else None,'category_results':groups,'corrected_errors':corrected,'regressions':regressed,'changed_predictions':sum(x['changed_decision'] for x in out),'exact_paired_p':pvalue,'invalid_outputs':invalid,'incomplete_outputs':incomplete,'token_cost_usd':cost,'reasoning_tokens':reasoning,'max_output_tokens_observed':max([r.load(H/'traces'/f"astra-{x['source_index']:03d}.json")['usage']['output_tokens'] for x in out],default=0),'verification':'Request, prompt, source, baseline and usage hashes verified; all non-input request fields identical to earlier Astra run.'}
(H/'results.json').write_text(json.dumps(res,indent=2))
if out:
 with (H/'All 20 decisions.csv').open('w') as f:
  w=csv.DictWriter(f,fieldnames=out[0].keys());w.writeheader();w.writerows(out)
if n==20:
 lines=['# Astra: publisher prompt, decision output only','','This is the requested decision-only test. No tutoring replies, student simulator or judge were used. We preserved the publisher\'s evaluation-aware teaching guidance and student metadata, removed only the multiple-message output instruction, supplied the complete pre-cut conversation, and asked for one word: scaffolding or rigor.','','## Results on the same 20 moments','','| Prompt | Correct /20 | Accuracy | Scaffolding /10 | Rigor /10 |','|---|---:|---:|---:|---:|',f"| Publisher prompt adapted for a decision | {newcorrect} | {newcorrect/20:.0%} | {groups['scaffolding']['new_correct']} | {groups['rigor']['new_correct']} |",f"| Previous revised decision prompt | {oldcorrect} | {oldcorrect/20:.0%} | {groups['scaffolding']['old_correct']} | {groups['rigor']['old_correct']} |",'',f"Previous errors corrected: {corrected}; new errors introduced: {regressed}; changed decisions: {res['changed_predictions']}. Exact paired two-sided p={pvalue:.4f}; the small sample does not establish general superiority or equivalence.",'',f"New token cost: **${cost:.4f}**, below the $2.50 ceiling. {invalid} invalid outputs and {incomplete} incomplete responses. Largest output including reasoning: {res['max_output_tokens_observed']} tokens against the4096-token ceiling. No additional runs or prompt variants were launched.",'','## What changed','','Only the API input text changed relative to the earlier decision run. Model, endpoint, reasoning effort, output ceiling and other request settings were identical: official OpenAI Responses API, gpt-6-astra, high reasoning,4096 output tokens including reasoning, default service tier, explicit cache mode without breakpoints and store=false. Each prompt is supplied as one input string. The original publisher prompt places instructions before context; this ordering is retained in the adaptation.','','The following instruction replaces the tutor-message output requirement:','','> '+(H/'decision-instruction.txt').read_text().strip(),'','There are no supplied teacher labels, hints, post-cut turns, prior predictions or oracle student traits. The20 moments and their order are exactly the earlier frozen sample, ten per category from20 distinct students. They were not selected again using model correctness. These are previously examined development materials, so the result is exploratory rather than held-out validation.','','This remains a forced binary decision task. The publisher\'s approximately92.7% Astra website score comes from a multi-turn tutoring task with different outcome scoring; this adaptation does not make those percentages interchangeable. The four tutoring replays run before this clarification are a separate, unintended-task experiment and are excluded from this decision result.','','## Artifacts','','- [Adapted prompt template](Adapted%20prompt.txt) and [exact output instruction](decision-instruction.txt).','- [All20 decisions](All%2020%20decisions.csv), [results](results.json), [frozen plan](PLAN.md), [hashes](frozen.json).','- `traces/` preserves every actual request and response. Only this model was called.','','Offline verification: `python3 experiments/astra-publisher-prompt-decisions/analyze.py`. Existing successful traces are never regenerated for reporting.','','[Publisher prompt](https://github.com/allenai/tutormoments/blob/main/src/tutormoments/prompts/tutor/scaffolding_rigor.txt), [TutorMoments](https://tutormoments.allen.ai/), [official Astra documentation](https://developers.openai.com/api/docs/models/gpt-6-astra).','']
 text='\n'.join(lines)
 for a,b in [('the4096','the 4096'),('reasoning,4096','reasoning, 4096'),('The20','The 20'),('from20','from 20'),('approximately92','approximately 92'),('All20','All 20')]:text=text.replace(a,b)
 (H/'README.md').write_text(text)
print(json.dumps(res,indent=2))
